import os
import json
import time
import logging
from typing import Any, Dict, Optional

import boto3
from botocore.exceptions import ClientError


class CloudWatchJSONLogger:
    def __init__(
        self,
        log_group_name: str,
        log_stream_name: str,
        region_name: Optional[str] = None,
    ) -> None:
        self.log_group_name = log_group_name
        self.log_stream_name = log_stream_name
        self.client = boto3.client(
            "logs",
            region_name=region_name or os.getenv("AWS_REGION") or os.getenv("AWS_DEFAULT_REGION") or "us-east-1",
        )
        self._ensure_log_group()
        self._ensure_log_stream()

    def _ensure_log_group(self) -> None:
        try:
            self.client.create_log_group(logGroupName=self.log_group_name)
        except ClientError as e:
            code = e.response.get("Error", {}).get("Code")
            if code != "ResourceAlreadyExistsException":
                raise

    def _ensure_log_stream(self) -> None:
        try:
            self.client.create_log_stream(
                logGroupName=self.log_group_name,
                logStreamName=self.log_stream_name,
            )
        except ClientError as e:
            code = e.response.get("Error", {}).get("Code")
            if code != "ResourceAlreadyExistsException":
                raise

    def write_json_event(self, event: Dict[str, Any]) -> Dict[str, Any]:
        payload = json.dumps(event, separators=(",", ":"), ensure_ascii=False)
        return self.client.put_log_events(
            logGroupName=self.log_group_name,
            logStreamName=self.log_stream_name,
            logEvents=[
                {
                    "timestamp": int(time.time() * 1000),
                    "message": payload,
                }
            ],
        )


def write_structured_log(
    event: Dict[str, Any],
    log_group_name: str,
    log_stream_name: str,
    region_name: Optional[str] = None,
) -> Dict[str, Any]:
    logger = CloudWatchJSONLogger(
        log_group_name=log_group_name,
        log_stream_name=log_stream_name,
        region_name=region_name,
    )
    return logger.write_json_event(event)
